globalCss:
/* Art Deco 全局样式 */

:root {
  --deco-gold: #d4af37;
  --deco-dark: #1a1a2e;
  --deco-navy: #2d2d44;
  --deco-cream: #f5f5dc;
}

/* 金色渐变 */
.deco-gold {
  background: linear-gradient(135deg, #d4af37 0%, #f5d67a 50%, #d4af37 100%);
}

/* 放射状线条 */
.deco-sunburst {
  background-image: repeating-conic-gradient(
    from 0deg,
    transparent 0deg 15deg,
    rgba(212, 175, 55, 0.1) 15deg 30deg
  );
}

/* 几何边框 */
.deco-border {
  border: 1px solid var(--deco-gold);
  position: relative;
}

.deco-border::before,
.deco-border::after {
  content: "";
  position: absolute;
  width: 20px;
  height: 20px;
  border: 2px solid var(--deco-gold);
}

.deco-border::before {
  top: -5px;
  left: -5px;
  border-right: none;
  border-bottom: none;
}

.deco-border::after {
  bottom: -5px;
  right: -5px;
  border-left: none;
  border-top: none;
}

/* 装饰分隔线 */
.deco-divider {
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--deco-gold), transparent);
}
@keyframes art-deco-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes art-deco-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.art-deco-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(212, 175, 55, 0.08);
}

.art-deco-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.art-deco-animate-in {
  animation: art-deco-fade-in 0.5s ease-out both;
}
